CREATE TABLE "ar_internal_metadata" ("key" varchar NOT NULL PRIMARY KEY, "value" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE "card_actions" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "card_id" integer, "card_act_id" integer, "super_action_id" integer, "action_type" integer, "draft" boolean, "comment" text);
CREATE TABLE "card_acts" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "card_id" integer, "actor_id" integer, "acted_at" datetime(6), "ip_address" varchar);
CREATE TABLE "card_changes" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "card_action_id" integer, "field" integer, "value" text(16777215));
CREATE TABLE "card_references" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "referer_id" integer DEFAULT 0 NOT NULL, "referee_key" varchar DEFAULT '', "referee_id" integer, "ref_type" varchar(1) DEFAULT '' NOT NULL, "is_present" integer);
CREATE TABLE "card_revisions" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "created_at" datetime(6) NOT NULL, "card_id" integer NOT NULL, "creator_id" integer NOT NULL, "content" text NOT NULL);
CREATE TABLE "card_virtuals" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "left_id" integer, "right_id" integer, "left_key" varchar, "content" text(16777215), "updated_at" datetime(6));
CREATE TABLE "cards" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar, "key" varchar, "codename" varchar, "left_id" integer, "right_id" integer, "current_revision_id" integer, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL, "creator_id" integer NOT NULL, "updater_id" integer NOT NULL, "read_rule_class" varchar, "read_rule_id" integer, "references_expired" integer, "trash" boolean NOT NULL, "type_id" integer NOT NULL, "db_content" text(16777215));
CREATE TABLE "delayed_jobs" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "priority" integer DEFAULT 0 NOT NULL, "attempts" integer DEFAULT 0 NOT NULL, "handler" text(16777215) NOT NULL, "last_error" text, "run_at" datetime(6), "locked_at" datetime(6), "failed_at" datetime(6), "locked_by" varchar, "queue" varchar, "created_at" datetime(6), "updated_at" datetime(6));
CREATE TABLE "library_assistant_decisions" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "viewer_user_id" varchar NOT NULL, "source" varchar DEFAULT 'panel' NOT NULL, "model" varchar, "state_hash" varchar(32) NOT NULL, "state_summary" varchar, "questions" text, "answers" text, "probabilities" text, "confidence" decimal(5,4), "cost_usd" decimal(14,8) DEFAULT 0.0, "input_tokens" integer DEFAULT 0, "output_tokens" integer DEFAULT 0, "fallback_reason" varchar, "thread_sid" varchar, "created_at" datetime(6) NOT NULL);
CREATE TABLE "library_assistant_interactions" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "viewer_user_id" varchar NOT NULL, "kind" varchar NOT NULL, "thread_sid" varchar, "exchange_index" integer, "payload" text, "tool_name" varchar, "referenced_card_path" varchar, "decision_id" integer, "cost_usd" decimal(14,8), "created_at" datetime(6) NOT NULL);
CREATE TABLE "library_assistant_learner_levels" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "viewer_user_id" varchar NOT NULL, "stack_layer" varchar NOT NULL, "sub_level" varchar, "level" integer DEFAULT 0 NOT NULL, "evidence_thread_sid" varchar, "evidence_quote" text, "changed_by" varchar DEFAULT 'agent' NOT NULL, "audit_note" text, "changed_at" datetime(6) NOT NULL);
CREATE TABLE "library_assistant_threads" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "sid" varchar NOT NULL, "user_id" varchar, "data" text, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE "library_audit_log" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "ts" datetime(6) DEFAULT CURRENT_TIMESTAMP NOT NULL, "actor" varchar NOT NULL, "action" varchar NOT NULL, "user_id" varchar, "user_email" varchar, "detail" text, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE "library_feature_events" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "user_id" varchar NOT NULL, "feature" varchar NOT NULL, "n" integer DEFAULT 0 NOT NULL, "first_at" datetime(6) NOT NULL, "last_at" datetime(6) NOT NULL);
CREATE TABLE "library_lib_settings" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "path" varchar NOT NULL, "value_json" text, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE "library_proposals" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "kind" varchar NOT NULL, "source" varchar DEFAULT 'pipeline' NOT NULL, "status" varchar DEFAULT 'pending' NOT NULL, "actor" varchar, "payload_json" text, "decision_json" text, "created_at" datetime(6) DEFAULT CURRENT_TIMESTAMP NOT NULL, "decided_at" datetime(6), "decided_by" varchar);
CREATE TABLE "schema_migrations" ("version" varchar NOT NULL PRIMARY KEY);
CREATE TABLE "sessions" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "session_id" varchar, "data" text, "updated_at" datetime(6));
CREATE TABLE "transform_migrations" ("version" varchar NOT NULL);
CREATE TABLE "users" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "login" varchar(40), "email" varchar(100), "crypted_password" varchar(40), "salt" varchar(42), "created_at" datetime(6), "updated_at" datetime(6), "password_reset_code" varchar(40), "status" varchar DEFAULT 'request', "invite_sender_id" integer, "identity_url" varchar, "card_id" integer NOT NULL, "account_id" integer NOT NULL);
